-- Expand the visual editor to every public route and keep published content public-only.
ALTER TABLE public.page_content DROP CONSTRAINT IF EXISTS page_content_page_id_check;
ALTER TABLE public.page_content ADD CONSTRAINT page_content_page_id_check
  CHECK (page_id IN ('home', 'shop', 'solutions', 'about', 'contact', 'category', 'product', 'work', 'services', 'studio'));
ALTER TABLE public.page_published_content DROP CONSTRAINT IF EXISTS page_published_content_page_id_check;
ALTER TABLE public.page_published_content ADD CONSTRAINT page_published_content_page_id_check
  CHECK (page_id IN ('home', 'shop', 'solutions', 'about', 'contact', 'category', 'product', 'work', 'services', 'studio'));

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_publication_tables
    WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = 'page_published_content'
  ) THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE public.page_published_content;
  END IF;
END $$;

