INSERT INTO public.page_published_content (page_id, document, revision)
SELECT page_id, published, published_revision FROM public.page_content
WHERE page_id IN ('shop', 'solutions', 'about', 'contact', 'category', 'product', 'work')
ON CONFLICT (page_id) DO NOTHING;
